import{C as e,U as t,_ as n,h as r,i,m as a,n as o,t as s,v as c}from"./theme-DsjXXSTJ.js";import{n as l,t as u}from"./index-BXC6e52-.js";var d={class:`lise-layout`},f=o(c({__name:`AgbView`,setup(o){return i(e=>({v57ceb628:t(s).dimensions.containerMaxWidth,a0bc8fe8:t(s).spacing.md,e46186cc:t(s).colors.neutral[50],v3ab955be:t(s).spacing[`2xl`],v2c16f473:t(s).colors.neutral[200],v0b07a18e:t(s).typography.fontFamily.sans,v0639ecd4:t(s).typography.fontSize[`3xl`],v9c55e2d2:t(s).typography.fontWeight.bold,v2c1a230c:t(s).colors.neutral[900],a0bc8d20:t(s).spacing.xs,v03a99c0c:t(s).typography.fontSize.base,v2c193a4e:t(s).colors.neutral[700],v18408654:t(s).dimensions.borderRadius.lg,a0bc8d2e:t(s).spacing.xl,v4b201f46:t(s).typography.fontSize.xl,v640d1e05:t(s).typography.fontWeight.semibold,a0bc8e62:t(s).spacing.sm})),(t,i)=>(e(),a(`div`,d,[n(l),i[0]||=r(`<main class="lise-main" data-v-47541e81><section class="lise-agb-hero" data-v-47541e81><div class="lise-container" data-v-47541e81><h1 class="lise-agb-hero__title" data-v-47541e81>Allgemeine Geschäftsbedingungen</h1><p class="lise-agb-hero__subtitle" data-v-47541e81> AGB für IT-Dienstleistungen und Softwareentwicklung der STN ENTERPRISES GmbH </p></div></section><section class="lise-agb-content" data-v-47541e81><div class="lise-container" data-v-47541e81><div class="lise-agb-card" data-v-47541e81><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 1 Geltungsbereich &amp; Vertragspartner</h2><p data-v-47541e81> (1) Diese Allgemeinen Geschäftsbedingungen (AGB) gelten für alle Verträge, Dienstleistungen und Angebote der <strong data-v-47541e81>STN ENTERPRISES GmbH</strong> (Märkischer Ring 92, 58097 Hagen, nachfolgend „Auftragnehmer“ genannt) gegenüber ihren Vertragspartnern (nachfolgend „Auftraggeber“ genannt). </p><p data-v-47541e81> (2) Diese AGB gelten ausschließlich gegenüber Unternehmern im Sinne des § 14 BGB, juristischen Personen des öffentlichen Rechts oder öffentlich-rechtlichen Sondervermögen. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 2 Vertragsgegenstand &amp; Leistungsumfang</h2><p data-v-47541e81> (1) Gegenstand des Vertrages ist die Erbringung von Dienstleistungen im Bereich der Softwareentwicklung, IT-Beratung, Cloud-Infrastruktur und UI/UX-Design gemäß dem jeweiligen Einzelauftrag oder Angebot. </p><p data-v-47541e81> (2) Der genaue Leistungsumfang, Termine sowie spezifische Anforderungen werden in individuellen Angeboten oder Leistungsbeschreibungen schriftlich festgelegt. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 3 Mitwirkungspflichten des Auftraggebers</h2><p data-v-47541e81> (1) Der Auftraggeber unterstützt den Auftragnehmer bei der Erbringung der vertraglich geschuldeten Leistungen durch rechtzeitige und unentgeltliche Bereitstellung aller erforderlichen Informationen, Daten, Zugänge und Ansprechpartner. </p><p data-v-47541e81> (2) Verzögerungen, die durch eine verspätete oder unvollständige Mitwirkung des Auftraggebers entstehen, führen zu einer entsprechenden Verschiebung der vereinbarten Ausführungstermine. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 4 Vergütung &amp; Zahlungsbedingungen</h2><p data-v-47541e81> (1) Die Vergütung richtet sich nach dem im jeweiligen Einzelvertrag vereinbarten Festpreis oder nach Aufwand auf Basis der aktuellen Stundensätze des Auftragnehmers. Alle Preise verstehen sich zuzüglich der gesetzlichen Mehrwertsteuer. </p><p data-v-47541e81> (2) Rechnungen sind innerhalb von 14 Tagen nach Rechnungsdatum ohne Abzug zur Zahlung fällig, sofern nicht anders schriftlich vereinbart. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 5 Nutzungs- &amp; Urheberrechte</h2><p data-v-47541e81> (1) Der Auftragnehmer räumt dem Auftraggeber mit vollständiger Bezahlung der geschuldeten Vergütung das einfache, übertragbare und zeitlich unbeschränkte Recht ein, die im Rahmen des Auftrags erstellte Software für eigene Geschäftszwecke zu nutzen. </p><p data-v-47541e81> (2) Die Einräumung ausschließlicher Nutzungsrechte bedarf einer ausdrücklichen schriftlichen Vereinbarung im Einzelvertrag. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 6 Haftung &amp; Mängelhaftung</h2><p data-v-47541e81> (1) Der Auftragnehmer haftet unbeschränkt für Vorsatz und grobe Fahrlässigkeit sowie für Schäden aus der Verletzung des Lebens, des Körpers oder der Gesundheit. </p><p data-v-47541e81> (2) Bei leicht fahrlässiger Verletzung wesentlicher Vertragspflichten (Kardinalpflichten) ist die Haftung des Auftragnehmers auf den vertragstypischen, vorhersehbaren Schaden begrenzt. </p></article><article class="lise-agb-block" data-v-47541e81><h2 data-v-47541e81>§ 7 Schlussbestimmungen &amp; Gerichtsstand</h2><p data-v-47541e81> (1) Es gilt das Recht der Bundesrepublik Deutschland unter Ausschluss des UN-Kaufrechts (CISG). </p><p data-v-47541e81> (2) Ausschließlicher Gerichtsstand für alle Streitigkeiten aus oder im Zusammenhang mit diesem Vertrag ist Hagen, Westfalen. </p></article></div></div></section></main>`,1),n(u,{companyName:`STN ENTERPRISES GmbH`})]))}}),[[`__scopeId`,`data-v-47541e81`]]);export{f as default};